azureLogAnalytics.query:
let saveLog = AppTraces
| where $__timeFilter(TimeGenerated)
| where AppRoleName == "rtp-sender"
| where Message startswith "Rtp to be sent saved with id:"
| extend DebtorSP = extract(@"service_provider:\s*(\S+)", 1, Message)
| project OperationId, DebtorSP;
let invitiConSuccesso = toscalar(
    AppTraces
    | where $__timeFilter(TimeGenerated)
    | where AppRoleName == "rtp-sender"
    | where Message startswith "Rtp sent successfully with id:"
    | join kind=inner saveLog on OperationId
    | summarize ["Invii con successo"] = count()
);
let rtpPagateInChannel = toscalar(
    AppTraces
    | where $__timeFilter(TimeGenerated)
    | where AppRoleName == "rtp-sender"
    | where Message startswith "Successfully updated paid RTP with same psp scenario."
    | summarize ["RTP Pagate In-Channel"] = count()
);
print ["In-Channel Settlement Rate %"] = round(100.0 * rtpPagateInChannel / iff(invitiConSuccesso == 0, 1, invitiConSuccesso), 2)

let cnclCount = toscalar(
    AppTraces
    | where $__timeFilter(TimeGenerated)
    | where AppRoleName == 'rtp-sender'
    | where Message startswith "Triggering CANCEL transition for RTP"
    | summarize errorCount = count()
);
let rjcrCount = toscalar(
    AppTraces
    | where $__timeFilter(TimeGenerated)
    | where AppRoleName == 'rtp-sender'
    | where Message startswith "Triggering ERROR_CANCEL transition for RTP"
    | summarize errorCount = count()
);
print ["Cancellation Success Rate %"] = round(100.0 * cnclCount / iff((cnclCount + rjcrCount) == 0, 1, cnclCount + rjcrCount), 2)

